# ============================================================
# 六、生态系统
# ============================================================
def _gen_ecosystem_questions() -> List[Dict]:
    qs = []

    qs.append(_make_question(
        "bio_hunan_eco_01",
        "【高频】生态系统的组成包括[]。",
        ["所有生物", "生物及其生活环境", "所有植物", "所有动物"], 1,
        "生态系统 = 生物群落（所有生物）+ 非生物环境（阳光、空气、水分、土壤等）。非生物部分为生物提供物质和能量，生物部分包括生产者、消费者、分解者。",
        "easy", "生态系统组成"
    ))

    qs.append(_make_question(
        "bio_hunan_eco_02",
        "【高频】食物链和食物网中，能量流动的特点是[]。",
        ["循环流动，逐级递增", "单向流动，逐级递减", "双向流动，逐级不变", "多向流动，逐级增加"], 1,
        "能量流动特点：①单向流动（沿食物链从生产者→消费者→分解者，不能倒流）②逐级递减（每一营养级只获得上一营养级10%-20%的能量，90%用于呼吸消耗或被分解者利用）。能量流动的起点：生产者固定的光能。",
        "medium", "能量流动"
    ))

    qs.append(_make_question(
        "bio_hunan_eco_03",
        "【高频】在生态系统中，细菌和真菌属于[]。",
        ["生产者", "消费者", "分解者", "非生物因素"], 2,
        "生态系统成分：①生产者（绿色植物）②消费者（动物）③分解者（细菌和真菌）。分解者将动植物遗体和粪便分解成无机物，归还土壤，供生产者重新利用，是生态系统中不可缺少的成分。",
        "easy", "分解者"
    ))

    qs.append(_make_question(
        "bio_hunan_eco_04",
        "【易错】'一山不容二虎'反映的生态学原理是[]。",
        ["生态系统自动调节能力有限", "能量流动逐级递减", "种内斗争", "栖息地破坏"], 1,
        "食物链中营养级越高的生物，获取的能量越少，个体数量越少（老虎是顶级消费者）。一山不容二虎是因为：能量逐级递减，高营养级生物需要很大的领地范围才能获取足够能量，一只虎的领地内无法养活两只虎。",
        "medium", "能量金字塔"
    ))

    return qs


# ============================================================
# 七、生物多样性与其他高频考点
# ============================================================
